import{_ as a,o as i,c as s,a2 as e}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"Встроенный провайдер памяти","description":"","frontmatter":{},"headers":[],"relativePath":"ru/integrations/providers/memory/builtin.md","filePath":"ru/integrations/providers/memory/builtin.md","lastUpdated":1792323081000}'),o={name:"ru/integrations/providers/memory/builtin.md"};function r(l,t,n,h,d,p){return i(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="встроенныи-проваидер-памяти" tabindex="-1">Встроенный провайдер памяти <a class="header-anchor" href="#встроенныи-проваидер-памяти" aria-label="Permalink to &quot;Встроенный провайдер памяти&quot;">​</a></h1><p>Встроенный провайдер памяти — это стандартный бэкенд памяти, поставляемый с Memoh. Он работает с конвейером памяти Memoh и поддерживает:</p><ul><li>автоматическое извлечение воспоминаний из разговоров;</li><li>семантический поиск воспоминаний во время чата;</li><li>ручное создание и правку воспоминаний;</li><li>процессы сжатия и перестроения памяти.</li></ul><hr><h2 id="как-это-работает" tabindex="-1">Как это работает <a class="header-anchor" href="#как-это-работает" aria-label="Permalink to &quot;Как это работает&quot;">​</a></h2><p>Встроенный провайдер работает в режиме <strong>graph</strong>. Узлы и рёбра памяти хранятся в PostgreSQL как источник истины, а из них выводится Markdown-представление (bundle <code>memory/</code> плюс <code>MEMORY.md</code> в рабочем пространстве Bot), которое агент читает и редактирует.</p><p>Семантический поиск необязателен и надстраивается сверху:</p><table tabindex="0"><thead><tr><th>Слой</th><th>Хранилище</th><th>Требования</th><th>Что добавляет</th></tr></thead><tbody><tr><td><strong>Graph</strong> (всегда включён)</td><td>Узлы/рёбра памяти в PostgreSQL</td><td>Ничего сверх основной базы данных</td><td>Структурированное извлечение, связи между воспоминаниями, сжатие, перестроение</td></tr><tr><td><strong>Семантический индекс</strong> (опционально)</td><td>База данных <code>pgvector</code></td><td>База <code>[pgvector]</code> из Compose-стека <strong>и</strong> модель эмбеддингов, выбранная на провайдере</td><td>Поиск по векторной близости среди узлов памяти</td></tr></tbody></table><p>Если модель эмбеддингов не задана или база <code>pgvector</code> не настроена, провайдер всё равно работает в чисто графовом режиме; семантический поиск просто пропускается.</p><hr><h2 id="создание-встроенного-проваидера" tabindex="-1">Создание встроенного провайдера <a class="header-anchor" href="#создание-встроенного-проваидера" aria-label="Permalink to &quot;Создание встроенного провайдера&quot;">​</a></h2><ol><li>Перейдите на страницу <strong>Memory Providers</strong>.</li><li>Нажмите <strong>Add Memory Provider</strong>.</li><li>Заполните поля: <ul><li><strong>Name</strong>: отображаемое имя этого провайдера.</li><li><strong>Provider Type</strong>: выберите <code>builtin</code>.</li></ul></li><li>Нажмите <strong>Create</strong>.</li></ol><hr><h2 id="настроика-встроенного-проваидера" tabindex="-1">Настройка встроенного провайдера <a class="header-anchor" href="#настроика-встроенного-проваидера" aria-label="Permalink to &quot;Настройка встроенного провайдера&quot;">​</a></h2><p>Создав провайдер, выберите его в списке и настройте параметры.</p><table tabindex="0"><thead><tr><th>Поле</th><th>Описание</th></tr></thead><tbody><tr><td><strong>Embedding Model</strong></td><td>Необязательно. Модель эмбеддингов от одного из ваших LLM-провайдеров. Когда она задана (и доступен <code>pgvector</code>), узлы памяти векторизуются и включается семантический поиск. Оставьте пустым для чисто графового режима.</td></tr></tbody></table><h3 id="управление-проваидерами" tabindex="-1">Управление провайдерами <a class="header-anchor" href="#управление-проваидерами" aria-label="Permalink to &quot;Управление провайдерами&quot;">​</a></h3><ul><li><strong>Edit</strong>: выберите провайдер и обновите его настройки.</li><li><strong>Delete</strong>: удалите провайдер, которым больше не пользуетесь.</li></ul><hr><h2 id="требования-к-инфраструктуре" tabindex="-1">Требования к инфраструктуре <a class="header-anchor" href="#требования-к-инфраструктуре" aria-label="Permalink to &quot;Требования к инфраструктуре&quot;">​</a></h2><h3 id="только-graph" tabindex="-1">Только graph <a class="header-anchor" href="#только-graph" aria-label="Permalink to &quot;Только graph&quot;">​</a></h3><p>Никакой дополнительной инфраструктуры сверх основной базы PostgreSQL.</p><h3 id="семантическии-индекс" tabindex="-1">Семантический индекс <a class="header-anchor" href="#семантическии-индекс" aria-label="Permalink to &quot;Семантический индекс&quot;">​</a></h3><p>Стандартный стек Docker Compose уже включает сервис <code>pgvector</code> и соответствующую секцию в <code>config.toml</code>:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pgvector</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">enabled = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">host = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pgvector&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">port = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5432</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">user = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;memoh&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">password = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;memoh123&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">database = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;memoh_vector&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sslmode = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;disable&quot;</span></span></code></pre></div><p>Затем выберите на провайдере <strong>Embedding Model</strong>. Эмбеддинги генерируются через выбранный LLM-провайдер (OpenAI, Gemini, Ollama, ...), поэтому у того провайдера должна быть модель с поддержкой эмбеддингов.</p><hr><h2 id="назначение-проваидера-памяти-bot" tabindex="-1">Назначение провайдера памяти Bot <a class="header-anchor" href="#назначение-проваидера-памяти-bot" aria-label="Permalink to &quot;Назначение провайдера памяти Bot&quot;">​</a></h2><ol><li>Перейдите на страницу <strong>Bots</strong> и откройте своего Bot.</li><li>Откройте вкладку <strong>General</strong>.</li><li>Найдите выпадающий список <strong>Memory Provider</strong>.</li><li>Выберите созданный провайдер.</li><li>Нажмите <strong>Save</strong>.</li></ol><p>Если провайдер памяти не выбран, Bot не будет использовать эту конфигурацию провайдера в своих рабочих настройках.</p><hr><h2 id="работа-с-памятью-после-настроики" tabindex="-1">Работа с памятью после настройки <a class="header-anchor" href="#работа-с-памятью-после-настроики" aria-label="Permalink to &quot;Работа с памятью после настройки&quot;">​</a></h2><p>Как только провайдер памяти назначен Bot, самими воспоминаниями можно управлять на вкладке <strong>Memory</strong> этого Bot:</p><ul><li>создавать воспоминания вручную;</li><li>извлекать воспоминания из разговоров;</li><li>искать, править и удалять воспоминания;</li><li>сжимать или перестраивать хранилище памяти.</li></ul><p>О повседневных операциях с памятью читайте дальше в <a href="./../../../guides/memory.html">Управлении памятью Bot</a>.</p>`,35)])])}const k=a(o,[["render",r]]);export{c as __pageData,k as default};
